"""policy.ini (docs/policy.md)."""

import re
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": 0,
           "compress_after": 1, "keep": 5, "keep_days": None}


def _bad(msg):
    raise DataError("policy", msg)


def _size(v):
    m = re.fullmatch(r"([0-9]+)([KMGkmg]?)", v)
    if not m:
        _bad(f"bad size {v!r}")
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _dur(v):
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        _bad(f"bad duration {v!r}")
    return int(m.group(1)) * {"m": 60, "h": 3600, "d": 86400}[m.group(2)]


def _off(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        _bad(f"bad offset {v!r}")
    s = int(m.group(2)) * 3600 + int(m.group(3)) * 60
    return -s if m.group(1) == "-" else s


def _int(minimum):
    def f(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            _bad(f"bad number {v!r}")
        return int(v)
    return f


def _off_or(parse):
    def f(v):
        return None if v == "off" else parse(v)
    return f


def _naming(v):
    if v not in ("numbered", "dated"):
        _bad(f"bad naming {v!r}")
    return v


PARSERS = {"max_size": _off_or(_size), "max_age": _off_or(_dur), "naming": _naming, "offset": _off,
           "compress_after": _int(0), "keep": _int(1), "keep_days": _off_or(_int(1))}


class Policy:
    def __init__(self, defaults, sections):
        self.defaults = defaults
        self.sections = sections

    def has(self, name):
        return name in self.sections

    def get(self, name):
        s = dict(BUILTIN)
        s.update(self.defaults)
        s.update(self.sections.get(name, {}))
        return s


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    defaults, sections, cur = {}, {}, None
    seen_defaults = False
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if not line.endswith("]"):
                _bad(f"bad line {line!r}")
            head = line[1:-1]
            if head == "defaults":
                if seen_defaults:
                    _bad("defaults twice")
                seen_defaults = True
                cur = defaults
            elif head.startswith("stream ") and streams.valid(head[7:]):
                if head[7:] in sections:
                    _bad(f"section {head} twice")
                cur = sections[head[7:]] = {}
            else:
                _bad(f"unknown section {head!r}")
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line {line!r}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in PARSERS:
            _bad(f"unknown key {key!r}")
        if key in cur:
            _bad(f"key {key} twice")
        cur[key] = PARSERS[key](value)
    return Policy(defaults, sections)
