"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused


def _archives(logdir, name, naming):
    """[(sortkey, filename, compressed)] for the archives of a stream; raises on same-place pairs."""
    if naming == "numbered":
        rx = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?")
    else:
        rx = re.compile(re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")
    found = {}
    if logdir.is_dir():
        for p in logdir.iterdir():
            if not p.is_file():
                continue
            m = rx.fullmatch(p.name)
            if not m:
                continue
            if naming == "numbered":
                key, gz = (int(m.group(1)),), bool(m.group(2))
            else:
                try:
                    d = date.fromisoformat(m.group(1))
                except ValueError:
                    continue
                key, gz = (d.toordinal(), int(m.group(2) or 1)), bool(m.group(3))
            if key in found:
                raise DataError("archives", f"{name}: two archives in the same place")
            found[key] = (p.name, gz)
    return found


def _check_state(entries, existing):
    for name in existing:
        e = entries.get(name)
        if e is None:
            continue
        if "opened" in e and dates.parse_time(e["opened"], True) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in e:
            a = e["archives"]
            if not isinstance(a, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for v in a.values():
                if dates.parse_time(v, True) is None:
                    raise DataError("state", f"{name}: bad archive time")
        if "rotations" in e:
            r = e["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: bad rotations")


def run(ctx, dry_run, force, wanted):
    pol = policy_mod.load(ctx.policy_path)
    st = ctx.state
    entries = st["streams"]
    existing = set(streams.active(ctx.data)) | set(pol.sections)
    _check_state(entries, existing)
    names = sorted(set(wanted)) if wanted else sorted(existing)
    for n in names:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")
    logdir = streams.logs_dir(ctx.data)
    now = ctx.now
    plans = []
    for n in names:
        plans.append(_plan(ctx, pol.get(n), n, entries.get(n, {}), logdir, force, now))

    out = []
    r = x = c = 0
    for p in plans:
        out.extend(p["lines"])
        r += p["rotated"]
        x += p["removed"]
        c += p["compressed"]
    out.append(f"{r} rotated, {x} removed, {c} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out
    for p in plans:
        _execute(logdir, p)
    for p in plans:
        entries[p["name"]] = p["entry"]
    state_mod.save(ctx.state_path, st)
    return out


def _plan(ctx, pol, name, entry, logdir, force, now):
    naming = pol["naming"]
    arch = _archives(logdir, name, naming)
    log = streams.log_path(ctx.data, name)
    why = None
    if not log.is_file():
        what = "no log"
    else:
        size = log.stat().st_size
        if size == 0:
            what = "empty"
        elif force:
            what, why = "rotate (forced)", True
        elif pol["max_size"] is not None and size >= pol["max_size"]:
            what, why = "rotate (size)", True
        else:
            what = "not due"
            if pol["max_age"] is not None:
                if "opened" in entry:
                    opened = dates.parse_time(entry["opened"], True)
                else:
                    with log.open("rb") as f:
                        first = f.readline().decode("utf-8", errors="replace")
                    opened = dates.parse_time(first.rstrip("\r\n").split(" ")[0])
                    first = None
                if opened is not None and (now - opened).total_seconds() >= pol["max_age"]:
                    what, why = "rotate (age)", True
    rotated = bool(why)
    times = entry.get("archives", {})
    # items: dict(key, old, gz, time, new)
    items = [{"key": k, "old": v[0], "gz": v[1], "new": False} for k, v in arch.items()]
    if rotated:
        if naming == "numbered":
            for it in items:
                it["key"] = (it["key"][0] + 1,)
            key = (0,)
            newname = None
        else:
            tz = timezone(timedelta(seconds=pol["offset"]))
            day = now.astimezone(tz).date().toordinal()
            used = {k[1] for k in arch if k[0] == day}
            if not used:
                k = 1
            else:
                k = 2
                while k in used:
                    k += 1
            key = (day, k)
        items.append({"key": key, "old": None, "gz": False, "new": True})
    items.sort(key=lambda i: i["key"], reverse=(naming == "dated"))
    # retention
    for pos, it in enumerate(items, 1):
        t = None if it["new"] else times.get(it["old"])
        t = now if it["new"] else (dates.parse_time(t, True) if t is not None else None)
        it["time"] = t
        it["raw"] = dates.stamp(now) if it["new"] else times.get(it["old"])
        it["drop"] = pos > pol["keep"] or (
            pol["keep_days"] is not None and t is not None and (now - t) >= timedelta(days=pol["keep_days"]))
    kept = [i for i in items if not i["drop"]]
    for pos, it in enumerate(kept, 1):
        it["compress"] = (not it["gz"]) and pos > pol["compress_after"]
    # names
    for pos, it in enumerate(kept, 1):
        gz = it["gz"] or it["compress"]
        if naming == "numbered":
            base = f"{name}.log.{pos}"
        elif it["new"]:
            d = date.fromordinal(it["key"][0]).isoformat()
            base = f"{name}.log.{d}" + (f".{it['key'][1]}" if it["key"][1] > 1 else "")
        else:
            base = it["old"][:-3] if it["gz"] else it["old"]
        it["final"] = base + (".gz" if gz else "")
    lines = [f"{name}: {what}"]
    compressed = removed = 0
    for it in kept:
        compressed += it["compress"]
        if it["new"]:
            lines.append(f"  new {it['final']}")
        elif it["final"] != it["old"]:
            lines.append(f"  {it['final']} <- {it['old']}")
        else:
            lines.append(f"  {it['final']}")
    for it in items:
        if it["drop"] and not it["new"]:
            lines.append(f"remove {it['old']}")
            removed += 1
    new_entry = {}
    if rotated:
        new_entry["opened"] = dates.stamp(now)
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_entry["archives"] = {it["final"]: it["raw"] for it in kept if it["raw"] is not None}
    return {"name": name, "lines": lines, "rotated": int(rotated), "removed": removed,
            "compressed": compressed, "items": items, "entry": new_entry, "log": log}


def _execute(logdir, plan):
    name = plan["name"]
    ops = []  # (tmp, final)
    n = 0
    for it in plan["items"]:
        if it["drop"]:
            if not it["new"]:
                (logdir / it["old"]).unlink()
            continue
        tmp = logdir / f".logkeep-{name}-{n}.tmp"
        n += 1
        src = plan["log"] if it["new"] else logdir / it["old"]
        if it["compress"]:
            tmp.write_bytes(gzip.compress(src.read_bytes(), mtime=0))
            if not it["new"]:
                src.unlink()
        elif it["new"] or it["final"] != it["old"]:
            src.rename(tmp)
        else:
            continue
        if it["new"]:
            plan["log"].touch()
        ops.append((tmp, logdir / it["final"]))
    if plan["rotated"] and any(i["new"] and i["drop"] for i in plan["items"]):
        plan["log"].write_bytes(b"")
    for tmp, final in ops:
        tmp.rename(final)
